<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Personal Expense Tracker</title>
    <style>
        body { font-family: sans-serif; max-width: 800px; margin: 20px auto; padding: 0 20px; color: #333; line-height: 1.5; }
        section { background: #f9f9f9; padding: 20px; border-radius: 8px; margin-bottom: 20px; border: 1px solid #ddd; }
        h2 { margin-top: 0; font-size: 1.2rem; border-bottom: 1px solid #ccc; padding-bottom: 10px; }
        .form-group { margin-bottom: 15px; display: flex; flex-wrap: wrap; gap: 10px; align-items: flex-end; }
        .input-item { display: flex; flex-direction: column; }
        label { font-size: 0.8rem; font-weight: bold; margin-bottom: 4px; }
        input, select { padding: 8px; border: 1px solid #ccc; border-radius: 4px; }
        #form-error { color: red; font-size: 0.9rem; min-height: 1.2em; margin-bottom: 10px; }
        button { cursor: pointer; padding: 8px 16px; border-radius: 4px; border: none; background: #007bff; color: white; font-weight: bold; }
        button:hover { background: #0056b3; }
        .filters { display: flex; gap: 20px; align-items: center; flex-wrap: wrap; background: #eee; }
        .summary-container { display: flex; justify-content: space-between; align-items: center; margin-bottom: 15px; padding: 10px; background: #fff; border: 1px solid #ddd; border-radius: 4px; }
        #total { font-size: 1.4rem; font-weight: bold; color: #2c3e50; }
        .cat-totals { display: flex; gap: 10px; flex-wrap: wrap; }
        .cat-total { font-size: 0.85rem; background: #e2e2e2; padding: 4px 8px; border-radius: 4px; border: 1px solid #ccc; }
        .expense-list { width: 100%; border-collapse: collapse; margin-top: 10px; }
        .expense { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr auto; gap: 10px; padding: 10px; border-bottom: 1px solid #eee; align-items: center; background: white; }
        .expense:nth-child(even) { background: #fafafa; }
        .exp-del { background: #dc3545; color: white; padding: 4px 8px; font-size: 0.8rem; }
        .exp-del:hover { background: #a71d2a; }
        .header-row { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr auto; gap: 10px; font-weight: bold; padding: 10px 0; border-bottom: 2px solid #333; }
    </style>
</head>
<body>

    <h1>Expense Tracker</h1>

    <!-- Entry Form -->
    <section>
        <h2>Add Expense</h2>
        <div id="form-error"></div>
        <div class="form-group">
            <div class="input-item">
                <label for="amount">Amount</label>
                <input type="number" id="amount" step="0.01" placeholder="0.00">
            </div>
            <div class="input-item">
                <label for="category">Category</label>
                <select id="category">
                    <option value="groceries">Groceries</option>
                    <option value="transport">Transport</option>
                    <option value="bills">Bills</option>
                    <option value="fun">Fun</option>
                </select>
            </div>
            <div class="input-item">
                <label for="date">Date</label>
                <input type="date" id="date">
            </div>
            <div class="input-item">
                <label for="note">Note (Optional)</label>
                <input type="text" id="note" placeholder="Lunch, gas etc.">
            </div>
            <button id="add-expense">Add Expense</button>
        </div>
    </section>

    <!-- Filters -->
    <section class="filters">
        <h2>Filters</h2>
        <div class="input-item">
            <label for="filter-category">Category</label>
            <select id="filter-category">
                <option value="all">All</option>
                <option value="groceries">Groceries</option>
                <option value="transport">Transport</option>
                <option value="bills">Bills</option>
                <option value="fun">Fun</option>
            </select>
        </div>
        <div class="input-item">
            <label for="filter-from">From</label>
            <input type="date" id="filter-from">
        </div>
        <div class="input-item">
            <label for="filter-to">To</label>
            <input type="date" id="filter-to">
        </div>
    </section>

    <!-- Summary & List -->
    <div class="summary-container">
        <div>Total Visible: <span id="total">0.00</span></div>
        <div class="cat-totals" id="category-summaries">
            <!-- JS will inject .cat-total elements here -->
        </div>
    </div>

    <div class="header-row">
        <span>Note / Date</span>
        <span>Category</span>
        <span>Date</span>
        <span>Amount</span>
        <span>Action</span>
    </div>
    <div id="expense-list">
        <!-- .expense rows go here -->
    </div>

    <script>
        // State management
        let expenses = JSON.parse(localStorage.getItem('expenses')) || [];
        const categories = ['groceries', 'transport', 'bills', 'fun'];

        // DOM Elements
        const amountInp = document.getElementById('amount');
        const categoryInp = document.getElementById('category');
        const dateInp = document.getElementById('date');
        const noteInp = document.getElementById('note');
        const addBtn = document.getElementById('add-expense');
        const errorDiv = document.getElementById('form-error');

        const filterCat = document.getElementById('filter-category');
        const filterFrom = document.getElementById('filter-from');
        const filterTo = document.getElementById('filter-to');

        const totalEl = document.getElementById('total');
        const catSummariesEl = document.getElementById('category-summaries');
        const listEl = document.getElementById('expense-list');

        // Initialize Category Summary Elements
        function initCategoryUI() {
            catSummariesEl.innerHTML = '';
            categories.forEach(cat => {
                const span = document.createElement('span');
                span.className = 'cat-total';
                span.setAttribute('data-cat', cat);
                span.textContent = `${cat}: 0.00`;
                catSummariesEl.appendChild(span);
            });
        }

        function save() {
            localStorage.setItem('expenses', JSON.stringify(expenses));
            render();
        }

        function render() {
            const catFilter = filterCat.value;
            const fromFilter = filterFrom.value;
            const toFilter = filterTo.value;

            // 1. Filter Logic
            const filtered = expenses.filter(exp => {
                const matchCat = (catFilter === 'all' || exp.category === catFilter);
                const matchFrom = (!fromFilter || exp.date >= fromFilter);
                const matchTo = (!toFilter || exp.date <= toFilter);
                return matchCat && matchFrom && matchTo;
            });

            // 2. Sort: Newest first (by date, then by id for stability)
            filtered.sort((a, b) => {
                if (b.date !== a.date) return b.date.localeCompare(a.date);
                return b.id - a.id;
            });

            // 3. Render List & Calculate Totals
            listEl.innerHTML = '';
            let grandTotal = 0;
            const catTotals = {};
            categories.forEach(c => catTotals[c] = 0);

            filtered.forEach(exp => {
                grandTotal += parseFloat(exp.amount);
                catTotals[exp.category] += parseFloat(exp.amount);

                const row = document.createElement('div');
                row.className = 'expense';
                row.innerHTML = `
                    <span>${exp.note || '-'}</span>
                    <span>${exp.category}</span>
                    <span>${exp.date}</span>
                    <span>${parseFloat(exp.amount).toFixed(2)}</span>
                    <button class="exp-del" onclick="deleteExpense(${exp.id})">Delete</button>
                `;
                listEl.appendChild(row);
            });

            // 4. Update Summary UI
            totalEl.textContent = grandTotal.toFixed(2);
            categories.forEach(cat => {
                const el = document.querySelector(`.cat-total[data-cat="${cat}"]`);
                if (el) el.textContent = `${cat}: ${catTotals[cat].toFixed(2)}`;
            });
        }

        function addExpense() {
            const amount = parseFloat(amountInp.value);
            const category = categoryInp.value;
            const date = dateInp.value;
            const note = noteInp.value;

            // Validation: empty, non-numeric (NaN), zero, or negative, or missing date
            if (isNaN(amount) || amount <= 0 || !date) {
                errorDiv.textContent = "Please enter a valid positive amount and a date.";
                return;
            }

            errorDiv.textContent = ""; // Clear error

            const newExpense = {
                id: Date.now(),
                amount,
                category,
                date,
                note
            };

            expenses.push(newExpense);
            save();

            // Reset specific field
            amountInp.value = '';
            noteInp.value = '';
        }

        function deleteExpense(id) {
            expenses = expenses.filter(e => e.id !== id);
            save();
        }

        // Event Listeners
        addBtn.addEventListener('click', addExpense);
        filterCat.addEventListener('change', render);
        filterFrom.addEventListener('input', render);
        filterTo.addEventListener('input', render);

        // Startup
        initCategoryUI();
        render();
    </script>
</body>
</html>
